sealed class PaymentState {}
class PaymentInitial extends PaymentState {}
class PaymentProcessing extends PaymentState { final double amount; PaymentProcessing(this.amount); }
class PaymentSuccess extends PaymentState { final String txId; PaymentSuccess(this.txId); }
class PaymentFailure extends PaymentState { final String error; PaymentFailure(this.error); }

String getStatus(PaymentState state) => switch (state) {
  PaymentInitial() => 'Ready',
  PaymentProcessing(:final amount) => 'Processing OMR $amount...',
  PaymentSuccess(:final txId) => 'Paid! Ref: $txId',
  // Notice: PaymentFailure is omitted
};

