Future<List<Transaction>> parseLargeStatement(String rawJson) async {
  return await Isolate.run(() {
    final decoded = jsonDecode(rawJson) as List<dynamic>;
    return decoded.map((e) => Transaction.fromJson(e)).toList();
  });
}

